-- FitFirst quick list (145 foods). Curated estimates, not lab measurements.
on conflict (source,source_id) do update set name=excluded.name,category=excluded.category,basis=excluded.basis,basis_grams=excluded.basis_grams,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g;
